def _s_score(values: list[Decimal]) -> int:
    """Kendall score ``S = sum_{i < j} sign(values[j] - values[i])`` with
    ``sign`` in ``{-1, 0, 1}``."""
    score = 0
    size = len(values)
    for i in range(size):
        for j in range(i + 1, size):
            if values[j] > values[i]:
                score += 1
            elif values[j] < values[i]:
                score -= 1
    return score


